{
  "hypothesis": "When small-cap stocks experience abnormally high-volume days, short-term reversals follow in next-period returns.",
  "factors": [
    {
      "name": "vol_reversal_rank",
      "expression": "RANK(TS_ZSCORE(TS_PCTCHANGE($volume, 5), 20))",
      "explanation": "Computes the rank of abnormal volume changes over 5 days, normalized by cross-sectional dispersion over 20 days, testing if high-volume days predict short-term reversals."
    },
    {
      "name": "vol_return_gap",
      "expression": "TS_QUANTILE($return, 20, 0.9) - TS_QUANTILE($return, 20, 0.1)",
      "explanation": "Measures the gap between top and bottom return quantiles over 20 days, capturing dispersion after high-volume events to identify reversal potential."
    },
    {
      "name": "vol_residual_signal",
      "expression": "REGRESI($return, $volume, 5) - MEAN($return, 5)",
      "explanation": "Calculates the residual return after regressing returns on volume over 5 days, isolating the portion of return not explained by volume, to detect reversal patterns."
    },
    {
      "name": "vol_skew_mad",
      "expression": "SKEW(TS_ZSCORE($return, 10)) / TS_MAD($return, 10)",
      "explanation": "Analyzes the skewness of return distributions relative to their MAD over 10 days, identifying asymmetric return patterns following high-volume days."
    },
    {
      "name": "vol_decay_signal",
      "expression": "DECAYLINEAR(TS_PCTCHANGE($volume, 5), 10) * TS_PCTCHANGE($return, 5)",
      "explanation": "Weights recent volume changes with a decaying function over 10 days and multiplies by return changes, testing if volume decay predicts return reversals."
    },
    {
      "name": "vol_cross_corr",
      "expression": "TS_CORR($volume, $return, 5) - TS_CORR($volume, $return, 20)",
      "explanation": "Compares the correlation between volume and returns over short and long horizons, detecting shifts in the relationship that may signal reversal opportunities."
    }
  ]
}

